// Realloc alias bug
void grow_buffer(int** buf, int old_size, int new_size) {
    int* old = *buf;
    *buf = (int*)realloc(*buf, new_size * sizeof(int));
    // old pointer is now dangling if realloc moved the block
    for (int i = old_size; i < new_size; i++) {
        old[i] = 0;
